contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address asset, uint256 depositAmount) public payable {
        require(asset != address(0), "zero asset");
        require(depositAmount > 0, "zero amount");

        c.initialize(address(this));

        uint256 beforeTotal = c.getTotalAssetDeposits(asset);
        uint256 beforeMinted = c.getRsETHAmountToMint(asset, depositAmount);

        bool reverted;
