contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 limit) public {
        address lrtConfigAddr = address(c.lrtConfig());
        require(lrtConfigAddr != address(0), "config not set");
        // Make the asset supported in the LRT config via its admin surface.
        // The test contract is the deployer of c and msg.sender for all calls, so it
        // may hold the required admin role on the config contract.
        // Use a low-level call so we do not need to know the config's exact interface name.
        (bool okAddAsset, ) = lrtConfigAddr.call(
            abi.encodeWithSignature("addSupportedAsset(address,uint256)", asset, limit)
        );
        require(okAddAsset, "could not add supported asset");

        uint256 depLimit = c.lrtConfig().depositLimitByAsset(asset);
        uint256 total = c.getTotalAssetDeposits(asset);
        uint256 current = c.getAssetCurrentLimit(asset);

        // General rule: the current limit is the configured deposit limit minus all
        // asset deposits tracked for that asset, whenever that subtraction is defined.
        assert(total <= depLimit && current == depLimit - total);
    }

    receive() external payable {}
}

