contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount) public payable {
        require(address(c.lrtConfig()) != address(0), "config not set");

        // if asset is not supported, the call must revert; we only assert on successful deposits
        bool supported = c.lrtConfig().isSupportedAsset(asset);
        if (!supported || amount == 0) {
            return;
        }

        uint256 before = IERC20(asset).balanceOf(address(c));
        bool reverted;
        try c.depositAsset(asset, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 after_ = IERC20(asset).balanceOf(address(c));
            assert(after_ == before + amount);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

