contract InvMutTest {
    C c;

    event AssetDeposit(address indexed asset, uint256 depositAmount, uint256 rsethMintAmount);

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 depositAmount) public {
        require(depositAmount > 0, "zero amount");
        require(c.lrtConfig().isSupportedAsset(asset), "unsupported asset");

        uint256 balanceBefore = IERC20(asset).balanceOf(address(this));
        require(balanceBefore >= depositAmount, "insufficient balance");

        IERC20(asset).approve(address(c), depositAmount);

        uint256 limit = c.getAssetCurrentLimit(asset);
        if (limit == 0) return;
        uint256 actualDeposit = depositAmount;
        if (actualDeposit > limit) {
            actualDeposit = limit;
        }

        bool reverted;
        try c.depositAsset(asset, actualDeposit) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = IERC20(asset).balanceOf(address(this));
        assert(balanceAfter == balanceBefore - actualDeposit);
    }

    receive() external payable {}
}

